fn get_commit_hash(repo_path: &Path) -> Option<String> {
    // Use git command to get HEAD commit
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("rev-parse")
        .arg("HEAD")
        .output()
        .ok()?;
    if output.status.success() {
        let hash = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if hash.len() >= 40 {
            return Some(hash);
        }
    }
    None
}

fn encode_file_uri(path_str: &str) -> String {
    // Replace non-alphanumeric with underscore to mimic original's file____ encoding
    // Original: file:// + path, then replace ':' '/' '.' with '_' ?
    // For simplicity, we will take "file://" + path_str and replace any character that is not alphanumeric with "_"
    let uri = format!("file://{}", path_str);
    let mut encoded = String::new();
    for c in uri.chars() {
        if c.is_alphanumeric() {
            encoded.push(c);
        } else {
            encoded.push('_');
        }
    }
    encoded
}

fn extract_challenges(repo_path: &Path, langs_filter: Option<Vec<String>>) -> Vec<String> {
    // Simple extraction: walk files, filter by extension
    let mut challenges = Vec::new();
    let lang_map: HashMap<&str, &str> = [
        ("rs", "rust"),
        ("ts", "typescript"),
        ("js", "javascript"),
        ("py", "python"),
        ("rb", "ruby"),
        ("go", "go"),
        ("swift", "swift"),
        ("kt", "kotlin"),
        ("java", "java"),
        ("php", "php"),
        ("cs", "csharp"),
        ("c", "c"),
        ("cpp", "cpp"),
        ("h", "c"),
        ("hpp", "cpp"),
        ("hs", "haskell"),
        ("dart", "dart"),
        ("scala", "scala"),
        ("zig", "zig"),
    ].iter().cloned().collect();

    let filter_set = langs_filter.map(|v| v.into_iter().collect::<std::collections::HashSet<_>>());

    for entry in walkdir::WalkDir::new(repo_path).into_iter().filter_map(|e| e.ok()) {
        if !entry.file_type().is_file() {
            continue;
        }
        let path = entry.path();
        // Skip .git
        if path.components().any(|c| c.as_os_str() == ".git") {
            continue;
        }
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if let Some(lang) = lang_map.get(ext) {
                if let Some(ref filter) = filter_set {
                    if !filter.contains(&lang.to_string()) {
                        continue;
                    }
                }
                // Read file and extract functions via regex
                if let Ok(content) = fs::read_to_string(path) {
                    // Simple regex for function definitions: def, fn, function, etc.
                    // We'll use regex crate
                    // For python: def <name>(
                    // For rust: fn <name>(
                    // For js/ts: function <name> or <name> = ( or def?
                    // For simplicity, count each file as having at least one challenge if it contains "def " or "fn " etc.
                    // Actually we need to produce challenges: each function is a challenge.
                    // Let's use simple heuristic: count occurrences of "def " or "fn " or "function " or "class " etc.
                    let func_regex = regex::Regex::new(r"(?m)^\s*(def |fn |function |class |pub fn |func )").unwrap();
                    for mat in func_regex.find_iter(&content) {
                        // For each match, create a challenge string as file path + line
                        challenges.push(format!("{}:{}", path.display(), mat.start()));
                    }
                    // If no matches but file has content, still count as 1 challenge?
                    if challenges.is_empty() && !content.trim().is_empty() {
                        // For empty extraction, we still count? Original for empty repo said no challenges and error.
                        // We'll not add.
                    }
                }
            }
        }
    }
    challenges
}

