fn handle_terminal_error(command_args: Vec<String>) {
    let now = Utc::now();
    let filename = format!("gittype_error_{}.log", now.format("%Y%m%d_%H%M%S"));
    // Write error log
    let mut content = String::new();
    content.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now.format("%Y-%m-%d %H:%M:%S")));
    content.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    content.push_str("ERROR MESSAGE: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)\n");
    content.push_str(&format!("EXECUTABLE: \"{}\"\n", std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display()));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    content.push_str(&format!("WORKING_DIR: \"{}\"\n", cwd.display()));
    content.push_str(&format!("COMMAND_ARGS: {:?}\n", command_args));
    content.push_str("OS: linux\n");
    content.push_str("ARCH: x86_64\n");
    let _ = fs::write(&filename, content);
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)");
    // Also log
    log_error(&format!("APPLICATION ERROR:\nERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {:?}\nOS: linux\nARCH: x86_64\n", 
        now.format("%Y-%m-%d %H:%M:%S"),
        std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display(),
        cwd.display(),
        command_args
    ));
}

fn handle_db_error(command_args: Vec<String>, table: &str) {
    let now = Utc::now();
    let filename = format!("gittype_error_{}.log", now.format("%Y%m%d_%H%M%S"));
    let mut content = String::new();
    content.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now.format("%Y-%m-%d %H:%M:%S")));
    content.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    content.push_str(&format!("ERROR MESSAGE: Database error: no such table: {}\n", table));
    content.push_str(&format!("CAUSED BY (level 1): no such table: {}\n", table));
    content.push_str("CAUSED BY (level 2): Error code 1: SQL error or missing database\n");
    content.push_str(&format!("EXECUTABLE: \"{}\"\n", std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display()));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    content.push_str(&format!("WORKING_DIR: \"{}\"\n", cwd.display()));
    content.push_str(&format!("COMMAND_ARGS: {:?}\n", command_args));
    content.push_str("OS: linux\n");
    content.push_str("ARCH: x86_64\n");
    let _ = fs::write(&filename, content);
    // For terminal case, original prints after entering alternate screen, but we will print after
    // We need to simulate alternate screen enter/leave if terminal
    if is_terminal() {
        // enter alternate screen and then leave, as original does
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}};
        let mut stdout = io::stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
    }
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: Database error: no such table: {}", table);
    eprintln!("\nCaused by:\n    0: no such table: {}\n    1: Error code 1: SQL error or missing database", table, table);
    log_error(&format!("APPLICATION ERROR:\nERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: Database error: no such table: {}\nCAUSED BY (level 1): no such table: {}\nCAUSED BY (level 2): Error code 1: SQL error or missing database\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {:?}\nOS: linux\nARCH: x86_64\n",
        now.format("%Y-%m-%d %H:%M:%S"),
        table,
        table,
        std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display(),
        cwd.display(),
        command_args
    ));
}

fn cache_stats() {
    init_logging();
    let cache_dir = get_cache_dir();
    if !cache_dir.exists() {
        println!("Challenge Cache Statistics:");
        println!("  Cached repositories: 0");
        println!("  Total size: 0 bytes");
        return;
    }
    let entries = fs::read_dir(&cache_dir).map(|e| e.count()).unwrap_or(0);
    // But original counts cached repositories, not files? In earlier test after 1 repo with 1 commit, it said 1. After 2 commits, would it say 2? Yes earlier after second commit it had 2 files, so count would be 2. So count files.
    // However our earlier test after first commit gave 1 file. So count files.
    let mut total_size: u64 = 0;
    let mut count = 0;
    if let Ok(read) = fs::read_dir(&cache_dir) {
        for entry in read.flatten() {
            if let Ok(meta) = entry.metadata() {
                if meta.is_file() {
                    total_size += meta.len();
                    count += 1;
                }
            }
        }
    }
    println!("Challenge Cache Statistics:");
    println!("  Cached repositories: {}", count);
    println!("  Total size: {} bytes", total_size);
}

fn cache_list() {
    init_logging();
    let cache_dir = get_cache_dir();
    if !cache_dir.exists() {
        println!("No cached challenges found.");
        return;
    }
    let mut files = vec![];
    if let Ok(read) = fs::read_dir(&cache_dir) {
        for entry in read.flatten() {
            if let Ok(meta) = entry.metadata() {
                if meta.is_file() {
                    files.push(entry.path());
                }
            }
        }
    }
    if files.is_empty() {
        println!("No cached challenges found.");
        return;
    }
    // For each file, try to extract key from decompressed content? For simplicity, we will generate key from file stem? But original displays keys like file____:hash.
    // We will attempt to read file and decompress to get key if possible, else use file name.
    // For our implementation, we stored cache files with content that includes key? Let's implement simple parsing: if file is gzip, decompress and try to find pattern.
    // For now, just list file names without extension as keys? But to match original format, we should attempt to reconstruct key as file____:hash? We can store key as first line of decompressed content? Let's try to implement: we will write cache files with format that includes key.
    // For listing, we will print "Cached repository keys:" and then each key.
    println!("Cached repository keys:");
    for file_path in files {
        // Try to read and decompress
        let key = extract_key_from_cache_file(&file_path).unwrap_or_else(|| {
            // fallback: file stem
            file_path.file_stem().and_then(|s| s.to_str()).unwrap_or("unknown").to_string()
        });
        println!("  {}", key);
    }
}

fn extract_key_from_cache_file(path: &Path) -> Option<String> {
    // Try to decompress and find key pattern: file__ etc.
    use std::io::Read;
    let file = fs::File::open(path).ok()?;
    let mut decoder = flate2::read::GzDecoder::new(file);
    let mut buf = Vec::new();
    decoder.read_to_end(&mut buf).ok()?;
    // The decompressed format we write will have key at start? Let's search for "file" prefix.
    // For original files, decompressed starts with \x08file____ etc. So it contains key.
    // We will try to parse as string and find "file" pattern.
    let text = String::from_utf8_lossy(&buf);
    // Look for something like file____:hash (64 hex)
    // For simplicity, if text contains "file", extract first occurrence.
    // Our own format: we will write key at beginning.
    // So just return first line up to null or newline.
    // For original format, it might be binary, but we can try to extract visible ascii.
    // We'll look for pattern "file" and then take up to 100 chars.
    if let Some(start) = text.find("file") {
        let substr = &text[start..];
        // take until next non-printable or space or null
        let end = substr.find(|c: char| c == '\0' || c == '\n' || c == '\r').unwrap_or(substr.len().min(100));
        let candidate = &substr[..end];
        // If candidate contains colon and looks like key, return it
        if candidate.contains(':') && candidate.len() > 5 {
            return Some(candidate.trim().to_string());
        }
    }
    None
}

