fn trending(language: Option<String>, repo_name: Option<String>, period: String) {
    init_logging();
    if !is_terminal() {
        let mut args = vec!["./executable".to_string(), "trending".to_string()];
        if let Some(lang) = &language {
            args.push(lang.clone());
        }
        if let Some(repo) = &repo_name {
            args.push(repo.clone());
        }
        handle_terminal_error(args);
        return;
    }
    use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
    use std::io::stdout;
    let mut stdout = stdout();
    let _ = execute!(stdout, EnterAlternateScreen, Hide);
    if language.is_none() {
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: TrendingLanguageSelection");
    } else {
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: TrendingRepositorySelection");
        // Simulate API fetch failure after 10 sec
        // For our implementation, we'll log warning after 10 sec? But to keep simple, log immediately.
        if language.is_some() {
            log_warn(&format!("gittype::domain::repositories::trending_repository - Failed to fetch trending repositories from API: HTTP request error: error sending request for url (https://api.ossinsight.io/v1/trends/repos/?period=past_24_hours&language={})", language.as_ref().unwrap()));
        }
    }
    // Wait for q
    let start = std::time::Instant::now();
    loop {
        if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                    break;
                }
            }
        }
        if start.elapsed().as_secs() > 15 {
            break;
        }
    }
    let _ = execute!(stdout, LeaveAlternateScreen, Show);
}

fn get_commit_hash(repo_path: &Path) -> Option<String> {
    // Use git command to get HEAD commit
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("rev-parse")
        .arg("HEAD")
        .output()
        .ok()?;
    if output.status.success() {
        let hash = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if hash.len() >= 40 {
            return Some(hash);
        }
    }
    None
}

fn encode_file_uri(path_str: &str) -> String {
    // Replace non-alphanumeric with underscore to mimic original's file____ encoding
    // Original: file:// + path, then replace ':' '/' '.' with '_' ?
    // For simplicity, we will take "file://" + path_str and replace any character that is not alphanumeric with "_"
    let uri = format!("file://{}", path_str);
    let mut encoded = String::new();
    for c in uri.chars() {
