        let _ = execute!(stdout, LeaveAlternateScreen, Show);
    }
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: Database error: no such table: {}", table);
    eprintln!("\nCaused by:\n    0: no such table: {}\n    1: Error code 1: SQL error or missing database", table, table);
    log_error(&format!("APPLICATION ERROR:\nERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: Database error: no such table: {}\nCAUSED BY (level 1): no such table: {}\nCAUSED BY (level 2): Error code 1: SQL error or missing database\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {:?}\nOS: linux\nARCH: x86_64\n",
        now.format("%Y-%m-%d %H:%M:%S"),
        table,
