                .value_name("FORMAT")
                .default_value("json")
                .help("Export format"))
            .arg(Arg::new("output")
                .long("output")
                .value_name("OUTPUT")
                .help("Output file path")))
        .subcommand(Command::new("cache")
            .about("Manage challenge cache")
            .subcommand(Command::new("stats")
                .about("Show cache statistics"))
            .subcommand(Command::new("clear")
                .about("Clear all cached challenges"))
            .subcommand(Command::new("list")
                .about("List cached repository keys")))
        .subcommand(Command::new("repo")
