                .long("period")
                .value_name("PERIOD")
                .default_value("daily")
                .help("Time period for trending (daily, weekly, monthly)\n\n[default: daily]")))
}

fn main() {
    let mut cmd = build_cli();
    // Manually check version
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|a| a == "--version" || a == "-V") && args.len() == 2 {
        println!("gittype 0.8.0");
        return;
    }

    let matches = cmd.clone().try_get_matches_from(std::env::args().collect::<Vec<_>>()).unwrap_or_else(|e| {
        // clap will print help/error itself? We need to replicate original behavior which prints help to stdout
        // For --help, clap's error prints help, we should just print and exit
        let _ = e.print();
        std::process::exit(e.exit_code());
    });

    // If help flag? clap handles

    // Extract top-level args
    let repo_spec = matches.get_one::<String>("repo").cloned();
