    let now = Utc::now();
    let filename = format!("gittype_error_{}.log", now.format("%Y%m%d_%H%M%S"));
    let mut content = String::new();
    content.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now.format("%Y-%m-%d %H:%M:%S")));
    content.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    content.push_str("ERROR MESSAGE: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)\n");
