    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    content.push_str(&format!("WORKING_DIR: \"{}\"\n", cwd.display()));
    content.push_str(&format!("COMMAND_ARGS: {:?}\n", command_args));
    content.push_str("OS: linux\n");
    content.push_str("ARCH: x86_64\n");
    let _ = fs::write(&filename, content);
    eprintln!("💾 Error details written to: {}", filename);
    eprintln!("Error: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)");
    log_error(&format!("APPLICATION ERROR:\nERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {:?}\nOS: linux\nARCH: x86_64\n", 
        now.format("%Y-%m-%d %H:%M:%S"),
        std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display(),
        cwd.display(),
        command_args
    ));
}

fn handle_db_error(command_args: Vec<String>, table: &str) {
    let now = Utc::now();
