    let mut content = String::new();
    content.push_str(&format!("ERROR OCCURRED AT: {} UTC\n", now.format("%Y-%m-%d %H:%M:%S")));
    content.push_str("ERROR TYPE: \"gittype::domain::error::GitTypeError\"\n");
    content.push_str(&format!("ERROR MESSAGE: Database error: no such table: {}\n", table));
    content.push_str(&format!("CAUSED BY (level 1): no such table: {}\n", table));
    content.push_str("CAUSED BY (level 2): Error code 1: SQL error or missing database\n");
    content.push_str(&format!("EXECUTABLE: \"{}\"\n", std::env::current_exe().unwrap_or_else(|_| PathBuf::from("./executable")).display()));
