fn is_git_repo(path: &Path) -> bool {
    let mut current = Some(path);
    while let Some(p) = current {
        if p.join(".git").exists() {
            return true;
        }
        current = p.parent();
    }
    false
}

fn build_cli() -> Command {
    Command::new("gittype")
        .version(VERSION)
        .about("A typing practice tool using your own code repositories - extracts all code chunks (functions, classes, methods, etc.)")
        .long_about("GitType turns your own source code into typing challenges. Practice typing by using functions, classes, and methods from your actual projects. \n\nExamples:\n  gittype                           # Use current directory\n  gittype /path/to/repo             # Use specific repository\n  gittype --repo owner/repo         # Clone and use GitHub repository\n  gittype --langs rust,python       # Filter by languages")
        .override_usage("executable [OPTIONS] [REPO_PATH] [COMMAND]")
        .arg(Arg::new("repo")
            .long("repo")
            .value_name("REPO")
            .help("GitHub repository URL or path to clone and play with. Supports formats:\n  - owner/repo\n  - https://github.com/owner/repo\n  - git@github.com:owner/repo.git"))
        .arg(Arg::new("langs")
            .long("langs")
            .value_name("LANGS")
            .help("Filter by programming languages (comma-separated). Supported languages:\n  rust, typescript, javascript, python, ruby, go, swift, kotlin, java, php, csharp, c, cpp, haskell, dart, scala, zig\n  Example: --langs rust,python,typescript"))
        .arg(Arg::new("repo_path")
            .value_name("REPO_PATH")
            .help("Repository path to extract code from"))
        .subcommand(Command::new("history")
            .about("Show session history"))
        .subcommand(Command::new("stats")
            .about("Show analytics"))
        .subcommand(Command::new("export")
            .about("Export session data")
            .arg(Arg::new("format")
                .long("format")
                .value_name("FORMAT")
                .default_value("json")
                .help("Export format"))
            .arg(Arg::new("output")
                .long("output")
                .value_name("OUTPUT")
                .help("Output file path")))
        .subcommand(Command::new("cache")
            .about("Manage challenge cache")
            .subcommand(Command::new("stats")
                .about("Show cache statistics"))
            .subcommand(Command::new("clear")
                .about("Clear all cached challenges"))
            .subcommand(Command::new("list")
                .about("List cached repository keys")))
        .subcommand(Command::new("repo")
            .about("Manage repositories")
            .subcommand(Command::new("list")
                .about("List all cached repositories"))
            .subcommand(Command::new("clear")
                .about("Clear all cached repositories")
                .arg(Arg::new("force")
                    .long("force")
                    .action(clap::ArgAction::SetTrue)
                    .help("Force clear without confirmation")))
            .subcommand(Command::new("play")
                .about("Play a cached repository interactively")))
        .subcommand(Command::new("trending")
            .about("Select and practice with trending repositories from GitHub")
            .arg(Arg::new("language")
                .value_name("LANGUAGE")
                .help("Programming language to filter trending repositories.\nSupported languages: C, C#, C++, Dart, Go, Haskell, Java, JavaScript, Kotlin, PHP, Python, Ruby, Rust, Scala, Swift, TypeScript, Zig"))
            .arg(Arg::new("repo_name")
                .value_name("REPO_NAME")
                .help("Specific repository name to select from trending list"))
            .arg(Arg::new("period")
                .long("period")
                .value_name("PERIOD")
                .default_value("daily")
                .help("Time period for trending (daily, weekly, monthly)\n\n[default: daily]")))
}

fn main() {
    let mut cmd = build_cli();
    // Manually check version
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|a| a == "--version" || a == "-V") && args.len() == 2 {
        println!("gittype 0.8.0");
        return;
    }

    let matches = cmd.clone().try_get_matches_from(std::env::args().collect::<Vec<_>>()).unwrap_or_else(|e| {
        // clap will print help/error itself? We need to replicate original behavior which prints help to stdout
        // For --help, clap's error prints help, we should just print and exit
        let _ = e.print();
        std::process::exit(e.exit_code());
    });

    // If help flag? clap handles

    // Extract top-level args
    let repo_spec = matches.get_one::<String>("repo").cloned();
    let langs = matches.get_one::<String>("langs").cloned();
    let repo_path = matches.get_one::<String>("repo_path").cloned();

    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        match sub_name {
