fn extract_key_from_cache_file(path: &Path) -> Option<String> {
    use std::io::Read;
    let file = fs::File::open(path).ok()?;
    let mut decoder = flate2::read::GzDecoder::new(file);
    let mut buf = Vec::new();
    decoder.read_to_end(&mut buf).ok()?;
    let text = String::from_utf8_lossy(&buf);
    if let Some(start) = text.find("file") {
        let substr = &text[start..];
        let end = substr.find(|c: char| c == '\0' || c == '\n' || c == '\r').unwrap_or(substr.len().min(100));
        let candidate = &substr[..end];
        if candidate.contains(':') && candidate.len() > 5 {
            return Some(candidate.trim().to_string());
        }
    }
    None
}

