fn get_commit_hash(repo_path: &Path) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("rev-parse")
        .arg("HEAD")
        .output()
        .ok()?;
    if output.status.success() {
        let hash = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if hash.len() >= 40 {
            return Some(hash);
        }
    }
    None
}

fn encode_file_uri(path_str: &str) -> String {
    let uri = format!("file://{}", path_str);
    let mut encoded = String::new();
    for c in uri.chars() {
        if c.is_alphanumeric() {
            encoded.push(c);
        } else {
            encoded.push('_');
        }
    }
    encoded
}

fn extract_challenges(repo_path: &Path, langs_filter: Option<Vec<String>>) -> Vec<String> {
    let mut challenges = Vec::new();
    let lang_map: HashMap<&str, &str> = [
        ("rs", "rust"),
        ("ts", "typescript"),
        ("js", "javascript"),
        ("py", "python"),
        ("rb", "ruby"),
        ("go", "go"),
        ("swift", "swift"),
        ("kt", "kotlin"),
        ("java", "java"),
        ("php", "php"),
        ("cs", "csharp"),
        ("c", "c"),
        ("cpp", "cpp"),
        ("h", "c"),
        ("hpp", "cpp"),
        ("hs", "haskell"),
        ("dart", "dart"),
        ("scala", "scala"),
        ("zig", "zig"),
    ].iter().cloned().collect();

    let filter_set = langs_filter.map(|v| v.into_iter().collect::<HashSet<_>>());

    for entry in walkdir::WalkDir::new(repo_path).into_iter().filter_map(|e| e.ok()) {
        if !entry.file_type().is_file() {
            continue;
        }
        let path = entry.path();
        if path.components().any(|c| c.as_os_str() == ".git") {
            continue;
        }
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if let Some(lang) = lang_map.get(ext) {
                if let Some(ref filter) = filter_set {
                    if !filter.contains(&lang.to_string()) {
                        continue;
                    }
                }
                if let Ok(content) = fs::read_to_string(path) {
                    let func_regex = regex::Regex::new(r"(?m)^\s*(def |fn |function |class |pub fn |func )").unwrap();
                    for mat in func_regex.find_iter(&content) {
                        challenges.push(format!("{}:{}", path.display(), mat.start()));
                    }
                }
            }
        }
    }
    challenges
}

