fn main() {
    let mut cmd = build_cli();
    let args: Vec<String> = std::env::args().collect();
    if args.len() == 2 && (args[1] == "--version" || args[1] == "-V") {
        println!("gittype 0.8.0");
        return;
    }

    let matches = cmd.clone().try_get_matches_from(std::env::args().collect::<Vec<_>>()).unwrap_or_else(|e| {
        let _ = e.print();
        std::process::exit(e.exit_code());
    });

    let repo_spec = matches.get_one::<String>("repo").cloned();
