    let actual_repo_path: PathBuf = if repo_path_opt.is_some() {
        PathBuf::from(repo_path_opt.clone().unwrap())
    } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    };

    if !actual_repo_path.exists() {
        let err_msg = format!("Failed to extract code chunks: Path does not exist: {}", actual_repo_path.display());
