                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let git_dir = actual_repo_path.join(".git");
    let is_git = git_dir.exists() || is_git_repo(&actual_repo_path);
    if !is_git {
        let err_msg = "Failed to extract code chunks: Git repository not found";
        log_error(&format!("gittype::presentation::tui::screens::loading_screen - Repository processing failed: {}", err_msg));
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
        use std::io::stdout;
        let mut stdout = stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let start = std::time::Instant::now();
        loop {
            if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let langs_filter = langs.as_ref().map(|s| s.split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>());
    let challenges = extract_challenges(&actual_repo_path, langs_filter);

    if challenges.is_empty() {
        let err_msg = "Failed to extract code chunks: Git repository not found";
        log_error(&format!("gittype::presentation::tui::screens::loading_screen - Repository processing failed: {}", err_msg));
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
        use std::io::stdout;
        let mut stdout = stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let start = std::time::Instant::now();
        loop {
            if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let commit_hash = get_commit_hash(&actual_repo_path).unwrap_or_else(|| "unknown".to_string());
    let repo_path_str_for_key = repo_path_opt.clone().unwrap_or_else(|| ".".to_string());
    let file_uri = format!("file://{}", repo_path_str_for_key);
    let encoded_key_prefix = encode_file_uri(&repo_path_str_for_key);
    let key = format!("{}:{}", encoded_key_prefix, commit_hash);
    let cache_dir = get_cache_dir();
    let _ = fs::create_dir_all(&cache_dir);
    let hash_input = format!("{}:{}", file_uri, commit_hash);
    let file_name_hash = {
        use sha2::{Sha256, Digest};
        let mut hasher = Sha256::new();
        hasher.update(hash_input.as_bytes());
        hex::encode(hasher.finalize())
    };
    let cache_file_path = cache_dir.join(format!("{}.bin", file_name_hash));
    let content_str = format!("{} challenges: {}", key, challenges.len());
    use flate2::write::GzEncoder;
    use flate2::Compression;
    use std::io::Write as IoWrite;
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    let _ = encoder.write_all(content_str.as_bytes());
    let compressed = encoder.finish().unwrap_or_else(|_| content_str.as_bytes().to_vec());
    let _ = fs::write(&cache_file_path, compressed);

    log_info(&format!("gittype::presentation::game::models::loading_steps::generating_step - Successfully cached {} challenges for {}", challenges.len(), file_uri));
    log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
    log_info("gittype::presentation::game::stage_repository - ✅ StageRepository: Title screen data ready (will be updated by ScreenManager)");
    log_info("gittype::presentation::tui::screens::loading_screen - Repository processing completed successfully");

    use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
    use std::io::stdout;
    let mut stdout = stdout();
    let _ = execute!(stdout, EnterAlternateScreen, Hide);
    let start = std::time::Instant::now();
    loop {
        if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
            }
        }
        if start.elapsed().as_secs() > 30 { break; }
    }
    let _ = execute!(stdout, LeaveAlternateScreen, Show);
}

fn is_git_repo(path: &Path) -> bool {
    let mut current = Some(path);
    while let Some(p) = current {
        if p.join(".git").exists() {
            return true;
        }
        current = p.parent();
    }
    false
}

fn build_cli() -> Command {
    Command::new("executable")
        .bin_name("executable")
        .version("0.8.0")
        .about("A typing practice tool using your own code repositories - extracts all code chunks (functions, classes, methods, etc.)")
        .long_about("GitType turns your own source code into typing challenges. Practice typing by using functions, classes, and methods from your actual projects. \n\nExamples:\n  gittype                           # Use current directory\n  gittype /path/to/repo             # Use specific repository\n  gittype --repo owner/repo         # Clone and use GitHub repository\n  gittype --langs rust,python       # Filter by languages")
        .arg(Arg::new("repo")
