                if let Some(out) = output {
                    eprintln!("💡 Requested output: {}", out);
                }
                eprintln!("💡 This feature is planned for a future release");
            },
            "cache" => {
                if let Some((cache_sub, _)) = sub_matches.subcommand() {
                    match cache_sub {
                        "stats" => cache_stats(),
                        "clear" => cache_clear(),
                        "list" => cache_list(),
                        _ => {
                            let mut sub_cmd = build_cli().find_subcommand("cache").unwrap().clone();
