fn get_commit_hash(repo_path: &Path) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("rev-parse")
        .arg("HEAD")
        .output()
        .ok()?;
    if output.status.success() {
        let hash = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if hash.len() >= 40 {
            return Some(hash);
        }
    }
    None
}

fn encode_file_uri(path_str: &str) -> String {
    let uri = format!("file://{}", path_str);
    let mut encoded = String::new();
    for c in uri.chars() {
        if c.is_alphanumeric() {
            encoded.push(c);
        } else {
            encoded.push('_');
        }
    }
    encoded
}

fn extract_challenges(repo_path: &Path, langs_filter: Option<Vec<String>>) -> Vec<String> {
    let mut challenges = Vec::new();
    let lang_map: HashMap<&str, &str> = [
        ("rs", "rust"),
        ("ts", "typescript"),
        ("js", "javascript"),
        ("py", "python"),
        ("rb", "ruby"),
        ("go", "go"),
        ("swift", "swift"),
        ("kt", "kotlin"),
        ("java", "java"),
        ("php", "php"),
        ("cs", "csharp"),
        ("c", "c"),
        ("cpp", "cpp"),
        ("h", "c"),
        ("hpp", "cpp"),
        ("hs", "haskell"),
        ("dart", "dart"),
        ("scala", "scala"),
        ("zig", "zig"),
    ].iter().cloned().collect();

    let filter_set = langs_filter.map(|v| v.into_iter().collect::<HashSet<_>>());

    for entry in walkdir::WalkDir::new(repo_path).into_iter().filter_map(|e| e.ok()) {
        if !entry.file_type().is_file() {
            continue;
        }
        let path = entry.path();
        if path.components().any(|c| c.as_os_str() == ".git") {
            continue;
        }
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if let Some(lang) = lang_map.get(ext) {
                if let Some(ref filter) = filter_set {
                    if !filter.contains(&lang.to_string()) {
                        continue;
                    }
                }
                if let Ok(content) = fs::read_to_string(path) {
                    let func_regex = regex::Regex::new(r"(?m)^\s*(def |fn |function |class |pub fn |func )").unwrap();
                    for mat in func_regex.find_iter(&content) {
                        challenges.push(format!("{}:{}", path.display(), mat.start()));
                    }
                }
            }
        }
    }
    challenges
}

fn game(repo_path_opt: Option<String>, repo_spec: Option<String>, langs: Option<String>) {
    init_logging();
    log_info("gittype::presentation::cli::commands::game - Starting GitType game session");
    if !is_terminal() {
        let mut args = vec!["./executable".to_string()];
        if let Some(ref rp) = repo_path_opt {
            args.push(rp.clone());
        }
        if let Some(ref rs) = repo_spec {
            args.push("--repo".to_string());
            args.push(rs.clone());
        }
        if let Some(ref l) = langs {
            args.push("--langs".to_string());
            args.push(l.clone());
        }
        handle_terminal_error(args);
        return;
    }
    log_warn("gittype::domain::repositories::version_repository - Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");

    let repo_path_str = if let Some(rp) = repo_path_opt.clone() {
        rp
    } else if repo_spec.is_some() {
        "".to_string()
    } else {
        ".".to_string()
    };

    if repo_spec.is_some() {
        log_info(&format!("gittype::presentation::cli::commands::game - Initializing all screens with GameData parameters: repo_spec=Some(\"{}\"), repo_path=None", repo_spec.as_ref().unwrap()));
        log_info(&format!("gittype::infrastructure::git::remote::remote_git_repository_client - Cloning repository: {}", repo_spec.as_ref().unwrap()));
    } else {
        log_info(&format!("gittype::presentation::cli::commands::game - Initializing all screens with GameData parameters: repo_spec=None, repo_path=Some(\"{}\")", repo_path_str));
    }

    log_info("gittype::presentation::tui::screen_manager - Initializing screen: Loading");
    log_info("gittype::presentation::game::models::loading_steps::database_init_step - DatabaseInitStep: Starting database initialization");
    for _ in 0..6 {
        log_info("gittype::presentation::tui::views::loading::loading_progress_view - UI: No progress found for DatabaseInit, available steps: []");
    }
    ensure_gittype_dirs();
    let db_path = get_db_path();
    if !db_path.exists() {
        let _ = fs::write(&db_path, "schema_version\nrepositories\nsessions\nchallenges\nstages\nsession_results\nstage_results\n");
        let custom_theme_path = get_home_gittype_dir().join("custom-theme.json");
        if !custom_theme_path.exists() {
            let _ = fs::write(&custom_theme_path, "{}");
        }
    }
    log_info("gittype::presentation::game::models::loading_steps::database_init_step - DatabaseInitStep: Database initialized successfully");
    log_info("gittype::presentation::game::models::loading_steps::database_init_step - DatabaseInitStep: Global session repository initialized successfully");
    for _ in 0..6 {
        log_info("gittype::presentation::tui::views::loading::loading_progress_view - UI: No progress found for DatabaseInit, available steps: []");
    }
    log_info("gittype::presentation::game::models::loading_steps::cache_check_step - No git repository info - skipping cache check");

    let actual_repo_path: PathBuf = if repo_path_opt.is_some() {
        PathBuf::from(repo_path_opt.clone().unwrap())
    } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    };

    if !actual_repo_path.exists() {
        let err_msg = format!("Failed to extract code chunks: Path does not exist: {}", actual_repo_path.display());
        log_error(&format!("gittype::presentation::tui::screens::loading_screen - Repository processing failed: {}", err_msg));
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
        use std::io::stdout;
        let mut stdout = stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let start = std::time::Instant::now();
        loop {
            if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let git_dir = actual_repo_path.join(".git");
    let is_git = git_dir.exists() || is_git_repo(&actual_repo_path);
    if !is_git {
        let err_msg = "Failed to extract code chunks: Git repository not found";
        log_error(&format!("gittype::presentation::tui::screens::loading_screen - Repository processing failed: {}", err_msg));
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
        use std::io::stdout;
        let mut stdout = stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let start = std::time::Instant::now();
        loop {
            if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let langs_filter = langs.as_ref().map(|s| s.split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>());
    let challenges = extract_challenges(&actual_repo_path, langs_filter);

    if challenges.is_empty() {
        let err_msg = "Failed to extract code chunks: Git repository not found";
        log_error(&format!("gittype::presentation::tui::screens::loading_screen - Repository processing failed: {}", err_msg));
        log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
        use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
        use std::io::stdout;
        let mut stdout = stdout();
        let _ = execute!(stdout, EnterAlternateScreen, Hide);
        let start = std::time::Instant::now();
        loop {
            if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
                }
            }
            if start.elapsed().as_secs() > 10 { break; }
        }
        let _ = execute!(stdout, LeaveAlternateScreen, Show);
        return;
    }

    let commit_hash = get_commit_hash(&actual_repo_path).unwrap_or_else(|| "unknown".to_string());
    let repo_path_str_for_key = repo_path_opt.clone().unwrap_or_else(|| ".".to_string());
    let file_uri = format!("file://{}", repo_path_str_for_key);
    let encoded_key_prefix = encode_file_uri(&repo_path_str_for_key);
    let key = format!("{}:{}", encoded_key_prefix, commit_hash);
    let cache_dir = get_cache_dir();
    let _ = fs::create_dir_all(&cache_dir);
    let hash_input = format!("{}:{}", file_uri, commit_hash);
    let file_name_hash = {
        use sha2::{Sha256, Digest};
        let mut hasher = Sha256::new();
        hasher.update(hash_input.as_bytes());
        hex::encode(hasher.finalize())
    };
    let cache_file_path = cache_dir.join(format!("{}.bin", file_name_hash));
    let content_str = format!("{} challenges: {}", key, challenges.len());
    use flate2::write::GzEncoder;
    use flate2::Compression;
    use std::io::Write as IoWrite;
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    let _ = encoder.write_all(content_str.as_bytes());
    let compressed = encoder.finish().unwrap_or_else(|_| content_str.as_bytes().to_vec());
    let _ = fs::write(&cache_file_path, compressed);

    log_info(&format!("gittype::presentation::game::models::loading_steps::generating_step - Successfully cached {} challenges for {}", challenges.len(), file_uri));
    log_info("gittype::presentation::tui::screen_manager - Initializing screen: Title");
    log_info("gittype::presentation::game::stage_repository - ✅ StageRepository: Title screen data ready (will be updated by ScreenManager)");
    log_info("gittype::presentation::tui::screens::loading_screen - Repository processing completed successfully");

    use crossterm::{execute, terminal::{EnterAlternateScreen, LeaveAlternateScreen}, cursor::{Hide, Show}, event::{self, Event, KeyCode}};
    use std::io::stdout;
    let mut stdout = stdout();
    let _ = execute!(stdout, EnterAlternateScreen, Hide);
    let start = std::time::Instant::now();
    loop {
        if event::poll(std::time::Duration::from_millis(200)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc { break; }
            }
        }
        if start.elapsed().as_secs() > 30 { break; }
    }
    let _ = execute!(stdout, LeaveAlternateScreen, Show);
}

fn is_git_repo(path: &Path) -> bool {
    let mut current = Some(path);
    while let Some(p) = current {
        if p.join(".git").exists() {
            return true;
        }
        current = p.parent();
    }
    false
}

