                .long("period")
                .value_name("PERIOD")
                .default_value("daily")
                .help("Time period for trending (daily, weekly, monthly)"))
            .arg(Arg::new("help")
                .short('h')
                .long("help")
                .action(clap::ArgAction::SetTrue)
                .help("Print help")))
}

fn main() {
    // Manual help handling before clap
    let raw_args: Vec<String> = std::env::args().collect();
    // Version handling
    if raw_args.len() == 2 && (raw_args[1] == "--version" || raw_args[1] == "-V") {
        println!("gittype 0.8.0");
        return;
    }
    if raw_args.len() >= 2 && (raw_args.iter().any(|a| a == "--help" || a == "-h")) {
        // Check if we should print hardcoded help
        if print_help_for_args(&raw_args) {
            return;
        }
    }

    let cmd = build_cli();
    let matches = cmd.try_get_matches_from(std::env::args().collect::<Vec<_>>()).unwrap_or_else(|e| {
        // For errors, clap prints error; we should just print and exit
        let _ = e.print();
        std::process::exit(e.exit_code());
    });

    // Check help flag manually for top-level and subcommands
    if matches.get_flag("help") {
        // Determine if --help or -h was used: check raw args
        if raw_args.contains(&"--help".to_string()) {
            print!("{}", HELP_LONG);
        } else {
            print!("{}", HELP_SHORT);
        }
        return;
    }
    if matches.get_flag("version") {
        println!("gittype 0.8.0");
        return;
    }

    let repo_spec = matches.get_one::<String>("repo").cloned();
    let langs = matches.get_one::<String>("langs").cloned();
    let repo_path = matches.get_one::<String>("repo_path").cloned();

    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        // Check help flag for subcommand
        if sub_matches.get_flag("help") {
            match sub_name {
                "history" => print!("{}", HISTORY_HELP),
                "stats" => print!("{}", STATS_HELP),
                "export" => print!("{}", EXPORT_HELP),
                "cache" => print!("{}", CACHE_HELP),
                "repo" => print!("{}", REPO_HELP),
                "trending" => {
                    if raw_args.contains(&"--help".to_string()) {
                        print!("{}", TRENDING_HELP_LONG);
                    } else {
                        print!("{}", TRENDING_HELP_SHORT);
                    }
                },
                _ => {}
            }
            return;
        }
        match sub_name {
            "history" => {
                init_logging();
                eprintln!("❌ History command is not yet implemented");
                eprintln!("💡 This feature is planned for a future release");
            },
            "stats" => {
                init_logging();
                eprintln!("❌ Stats command is not yet implemented");
                eprintln!("💡 This feature is planned for a future release");
            },
            "export" => {
                if sub_matches.get_flag("help") {
                    print!("{}", EXPORT_HELP);
                    return;
                }
                init_logging();
                let format = sub_matches.get_one::<String>("format").cloned().unwrap_or_else(|| "json".to_string());
                let output = sub_matches.get_one::<String>("output").cloned();
                eprintln!("❌ Export command is not yet implemented");
                eprintln!("💡 Requested format: {}", format);
                if let Some(out) = output {
                    eprintln!("💡 Requested output: {}", out);
                }
                eprintln!("💡 This feature is planned for a future release");
            },
            "cache" => {
                if sub_matches.get_flag("help") {
                    print!("{}", CACHE_HELP);
                    return;
                }
                if let Some((cache_sub, cache_sub_matches)) = sub_matches.subcommand() {
                    if cache_sub_matches.get_flag("help") {
                        match cache_sub {
                            "stats" => print!("{}", CACHE_STATS_HELP),
                            "clear" => print!("{}", CACHE_CLEAR_HELP),
                            "list" => print!("{}", CACHE_LIST_HELP),
                            _ => {}
                        }
                        return;
                    }
                    match cache_sub {
                        "stats" => cache_stats(),
                        "clear" => cache_clear(),
                        "list" => cache_list(),
                        _ => {}
                    }
                } else {
                    print!("{}", CACHE_HELP);
                }
            },
            "repo" => {
                if sub_matches.get_flag("help") {
                    print!("{}", REPO_HELP);
                    return;
                }
                if let Some((repo_sub, repo_sub_matches)) = sub_matches.subcommand() {
                    if repo_sub_matches.get_flag("help") {
                        match repo_sub {
                            "list" => print!("{}", REPO_LIST_HELP),
                            "clear" => print!("{}", REPO_CLEAR_HELP),
                            "play" => print!("{}", REPO_PLAY_HELP),
                            _ => {}
                        }
                        return;
                    }
                    match repo_sub {
                        "list" => repo_list(),
                        "clear" => {
                            let force = repo_sub_matches.get_flag("force");
                            repo_clear(force);
                        },
                        "play" => repo_play(),
                        _ => {}
                    }
                } else {
                    print!("{}", REPO_HELP);
                }
            },
            "trending" => {
                if sub_matches.get_flag("help") {
                    if raw_args.contains(&"--help".to_string()) {
                        print!("{}", TRENDING_HELP_LONG);
                    } else {
                        print!("{}", TRENDING_HELP_SHORT);
                    }
                    return;
                }
                let language = sub_matches.get_one::<String>("language").cloned();
                let repo_name = sub_matches.get_one::<String>("repo_name").cloned();
                let period = sub_matches.get_one::<String>("period").cloned().unwrap_or_else(|| "daily".to_string());
                trending(language, repo_name, period);
            },
            _ => {}
        }
        return;
    }

    game(repo_path, repo_spec, langs);
}
